package com.mohymods.kingdomsmp.bounty;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.contribution.ContributionService;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.network.CommerceView;
import com.mohymods.kingdomsmp.persistence.*;
import com.mohymods.kingdomsmp.profession.ContractRules;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import java.io.IOException;
import java.util.*;
/** Partial real community deliveries at the Tier3 Bounty Master, funded once through canonical private mail. */
public final class CommunityContractService {
 public record Quote(UUID nonce,long revision,CommunityContractRules.Terms terms,long week,int quantity,List<ItemStack> inventory,long issued,String text){
  public Quote{inventory=inventory.stream().map(ItemStack::copy).toList();}
  @Override public List<ItemStack> inventory(){return inventory.stream().map(ItemStack::copy).toList();}
 }
 private static final Map<ServerPlayer,Quote> QUOTES=new WeakHashMap<>();
 private CommunityContractService(){ }
 public static void initialize(MinecraftServer server){CommunityContractRules.clear(server);QUOTES.keySet().removeIf(p->p.server==server);}
 public static void close(ServerPlayer p){QUOTES.remove(p);}
 public static Optional<Quote> quote(ServerPlayer p){var q=QUOTES.get(p);if(q!=null&&(q.revision()!=CommerceService.store(p.server).revision()||q.week()!=ContractRules.period("weekly")||System.nanoTime()-q.issued()>30_000_000_000L)){close(p);q=null;}return Optional.ofNullable(q);}
 public static boolean built(ServerPlayer p){return ContributionService.kingdom(p.server).attainedTier()>=3&&ConstructionService.store(p.server).projects().stream().anyMatch(v->v.blueprint().equals(RoyalBountyHallBlueprint.ID)&&v.phase()==ConstructionStore.Phase.COMPLETE&&!v.npcDead()&&ConstructionService.structureIntact(p.serverLevel(),v));}
 public static void requireCounter(ServerPlayer p){CommerceService.requireResidentCounter(p);if(!built(p))throw new IllegalStateException("Requires Tier3 and the completed intact Royal Bounty Hall.");boolean nearby=ConstructionService.store(p.server).projects().stream().filter(v->v.blueprint().equals(RoyalBountyHallBlueprint.ID)).anyMatch(v->{var e=p.serverLevel().getEntity(v.npc());return e instanceof com.mohymods.kingdomsmp.npc.ReeveEntity npc&&ConstructionService.registeredReeve(npc)&&p.distanceToSqr(npc)<=64&&p.hasLineOfSight(npc);});if(!nearby)throw new IllegalStateException("Deliver community supplies to the assigned Bounty Master within eight blocks and clear sight.");}
 private static CommunityContractRules.Terms terms(ServerPlayer p,String id,long week){var configured=CommunityContractRules.get(p.server).get(id);var pinned=CommerceService.store(p.server).communityProject(id,week).orElse(null);return pinned==null?configured:new CommunityContractRules.Terms(id,configured.title(),pinned.item(),pinned.goal(),pinned.unitReward(),pinned.budget());}
 private static Item item(CommunityContractRules.Terms t){var id=ResourceLocation.parse(t.item());if(!BuiltInRegistries.ITEM.containsKey(id))throw new IllegalStateException("Community item is not registered");return BuiltInRegistries.ITEM.get(id);}
 private static void spread(ServerPlayer p,CommunityContractRules.Terms t){for(var supply:CommerceService.catalog(p.server).supplies())if(supply.item()==item(t)&&t.unitReward()>=MarketService.catalog(p.server).rule(supply.id()).minimumSell())throw new IllegalStateException("Community payout would permit a profitable NPC stock loop; lower its configurable rate.");}
 public static Quote review(ServerPlayer p,String selected,int requested)throws IOException{
  requireCounter(p);if(!selected.startsWith("bounty:"))throw new IllegalArgumentException("Choose a community contract");var store=CommerceService.store(p.server);CommerceService.verifyReceipt(p,store);long week=ContractRules.period("weekly");var terms=terms(p,selected.substring(7),week);spread(p,terms);int delivered=store.communityProject(terms.id(),week).map(CommunityContractState.Project::delivered).orElse(0);var plain=new ItemStack(item(terms));int available=0;List<ItemStack> inventory=new ArrayList<>();for(int i=0;i<36;i++){var stack=p.getInventory().getItem(i);inventory.add(stack.copy());if(ItemStack.isSameItemSameComponents(stack,plain))available+=stack.getCount();}int quantity=Math.min(Math.min(64,Math.max(1,requested)),Math.min(available,terms.goal()-delivered));if(quantity<1)throw new IllegalStateException("Bring plain supplies for this unfinished community project. Nothing consumed.");long reward=Math.multiplyExact((long)quantity,terms.unitReward());if(reward>terms.budget()-store.communitySpent(week))throw new IllegalStateException("Shared weekly community reward pool exhausted");String text="Permanently contribute "+quantity+" plain "+plain.getHoverName().getString()+" to "+terms.title()+"; shared progress "+delivered+" / "+terms.goal()+". Receive "+reward+" coins through private mail. The completed project's Master Farmer proof requires at least 10% of its goal personally delivered during the Master trial band; other contributions still receive payment. Your contribution helps the whole kingdom. Claim your coins from the Mailbox after delivery. Weekly reset: Monday at 00:00 UTC.";var q=new Quote(UUID.randomUUID(),store.revision(),terms,week,quantity,inventory,System.nanoTime(),text);QUOTES.put(p,q);return q;
 }
 public static String confirm(ServerPlayer p,UUID nonce)throws IOException{
  var q=QUOTES.remove(p);var store=CommerceService.store(p.server);CommerceService.verifyReceipt(p,store);if(q==null||!q.nonce().equals(nonce)||q.revision()!=store.revision()||q.week()!=ContractRules.period("weekly")||System.nanoTime()-q.issued()>30_000_000_000L)throw new IllegalStateException("Community review expired or shared progress changed; review again.");requireCounter(p);spread(p,q.terms());var inventory=q.inventory();for(int i=0;i<36;i++)if(!ItemStack.matches(p.getInventory().getItem(i),inventory.get(i)))throw new IllegalStateException("Inventory changed; review community contribution again.");var old=p.getPersistentData().copy();boolean checkpointStarted=false;
  try{CommerceService.checkpoint(p);var t=q.terms();var pending=store.prepareCommunityDelivery(q.nonce(),p.getUUID(),t.id(),q.week(),t.item(),q.quantity(),t.goal(),t.unitReward(),t.budget());int left=q.quantity();var plain=new ItemStack(item(t));for(int i=0;i<36&&left>0;i++){var stack=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(stack,plain)){int n=Math.min(left,stack.getCount());stack.shrink(n);left-=n;}}if(left!=0)throw new IllegalStateException("Community inventory changed during commit");CommerceService.putReceipt(p,new EconomyStore.Receipt(store.id(),pending.sequence()));checkpointStarted=true;CommerceService.checkpoint(p);if(!store.recoverItem(CommerceService.receipt(AtomicNbt.read(CommerceService.playerFile(p.server,p.getUUID())))))throw new IOException("Community native receipt not committed");p.getInventory().setChanged();p.inventoryMenu.sendAllDataToRemote();return "Community contribution saved once; exact funded coins await in your Mailbox. Shared progress and individual recognition are persistent.";}
  catch(IOException|RuntimeException e){if(!checkpointStarted){for(int i=0;i<36;i++)p.getInventory().setItem(i,inventory.get(i).copy());for(var key:new HashSet<>(p.getPersistentData().getAllKeys()))p.getPersistentData().remove(key);p.getPersistentData().merge(old);}if(!checkpointStarted&&store.pendingItem().isEmpty()&&!store.quarantined()&&(e instanceof IllegalArgumentException||e instanceof IllegalStateException))throw e;store.quarantine();p.connection.disconnect(net.minecraft.network.chat.Component.literal("Community inventory interrupted; matching checkpoint recovery required."));throw e;}
 }
 public static List<CommerceView.Entry> entries(ServerPlayer p){var store=CommerceService.store(p.server);long week=ContractRules.period("weekly");boolean built=built(p);List<CommerceView.Entry> rows=new ArrayList<>();for(var configured:CommunityContractRules.get(p.server).all()){var t=terms(p,configured.id(),week);var project=store.communityProject(t.id(),week).orElse(null);int delivered=project==null?0:project.delivered();rows.add(new CommerceView.Entry("bounty:"+t.id(),t.title(),"Shared "+delivered+"/"+t.goal()+" "+new ItemStack(item(t)).getHoverName().getString()+". "+t.unitReward()+" coins/item; up to 64 per batch. Weekly pool "+store.communitySpent(week)+"/"+t.budget()+". Deliver at Tier3 Bounty Master. Master trial credit: personally supply 10% during your trials.",0,project!=null&&project.complete()?"COMPLETE":built?"COMMUNITY":"LOCKED"));}return List.copyOf(rows);}
}
